<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>2048</title>
<style>
  :root {
    --bg: #12141a;
    --panel: #1c2029;
    --cell: #262b36;
    --text: #e8eaf0;
    --muted: #9aa3b2;
    --accent: #f0a63c;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    padding: 0;
    min-height: 100%;
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    gap: 18px;
    padding: 24px 12px;
  }
  h1 {
    margin: 0;
    font-size: 40px;
    letter-spacing: 2px;
    color: var(--accent);
  }
  #hud {
    display: flex;
    align-items: center;
    gap: 14px;
  }
  .scorebox {
    background: var(--panel);
    border-radius: 8px;
    padding: 8px 18px;
    text-align: center;
    min-width: 110px;
  }
  .scorebox .label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: var(--muted);
  }
  #score {
    font-size: 24px;
    font-weight: 700;
  }
  #reset {
    background: var(--accent);
    color: #1a1206;
    border: 0;
    border-radius: 8px;
    padding: 12px 20px;
    font-size: 15px;
    font-weight: 700;
    cursor: pointer;
  }
  #reset:hover { filter: brightness(1.08); }
  #board {
    display: grid;
    grid-template-columns: repeat(4, 90px);
    grid-template-rows: repeat(4, 90px);
    gap: 10px;
    background: var(--panel);
    padding: 10px;
    border-radius: 10px;
  }
  .tile {
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--cell);
    border-radius: 8px;
    font-size: 30px;
    font-weight: 700;
    color: var(--text);
  }
  .tile.empty { color: transparent; }
  .v2    { background: #3a4152; }
  .v4    { background: #45506b; }
  .v8    { background: #6b5a34; color: #fff3dd; }
  .v16   { background: #86602f; color: #fff3dd; }
  .v32   { background: #9c5a30; color: #fff3dd; }
  .v64   { background: #b04d2a; color: #fff3dd; }
  .v128  { background: #b8912c; color: #fff8e0; font-size: 26px; }
  .v256  { background: #c09a24; color: #fff8e0; font-size: 26px; }
  .v512  { background: #c8a41c; color: #fff8e0; font-size: 26px; }
  .v1024 { background: #d0ae14; color: #fff8e0; font-size: 21px; }
  .v2048 { background: #e0bb00; color: #fff8e0; font-size: 21px; }
  .vbig  { background: #2f7f6f; color: #ffffff; font-size: 19px; }
  #hint { color: var(--muted); font-size: 13px; }
</style>
</head>
<body>
  <h1>2048</h1>
  <div id="hud">
    <div class="scorebox">
      <div class="label">Score</div>
      <div id="score">0</div>
    </div>
    <button id="reset" type="button">New Game</button>
  </div>
  <div id="board" aria-label="2048 board"></div>
  <div id="hint">Use the arrow keys to move the tiles.</div>

<script>
(function () {
  var SIZE = 4;
  var grid = [];
  var score = 0;

  var boardEl = document.getElementById('board');
  var scoreEl = document.getElementById('score');
  var resetEl = document.getElementById('reset');

  function emptyGrid() {
    var g = [];
    for (var r = 0; r < SIZE; r++) {
      var row = [];
      for (var c = 0; c < SIZE; c++) row.push(0);
      g.push(row);
    }
    return g;
  }

  function cloneGrid(g) {
    return g.map(function (row) { return row.slice(); });
  }

  function emptyCells() {
    var cells = [];
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        if (grid[r][c] === 0) cells.push([r, c]);
      }
    }
    return cells;
  }

  function spawn() {
    var cells = emptyCells();
    if (!cells.length) return false;
    var pick = cells[Math.floor(Math.random() * cells.length)];
    grid[pick[0]][pick[1]] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  // Slide + merge a single line toward index 0. Returns {line, gained}.
  function collapse(line) {
    var vals = line.filter(function (v) { return v !== 0; });
    var out = [];
    var gained = 0;
    for (var i = 0; i < vals.length; i++) {
      if (i + 1 < vals.length && vals[i] === vals[i + 1]) {
        var merged = vals[i] * 2;
        out.push(merged);
        gained += merged;
        i++; // each tile merges at most once per move
      } else {
        out.push(vals[i]);
      }
    }
    while (out.length < SIZE) out.push(0);
    return { line: out, gained: gained };
  }

  // Extract a line in move order for the given direction.
  function readLine(dir, i) {
    var line = [];
    for (var j = 0; j < SIZE; j++) {
      if (dir === 'left') line.push(grid[i][j]);
      else if (dir === 'right') line.push(grid[i][SIZE - 1 - j]);
      else if (dir === 'up') line.push(grid[j][i]);
      else line.push(grid[SIZE - 1 - j][i]);
    }
    return line;
  }

  function writeLine(dir, i, line) {
    for (var j = 0; j < SIZE; j++) {
      if (dir === 'left') grid[i][j] = line[j];
      else if (dir === 'right') grid[i][SIZE - 1 - j] = line[j];
      else if (dir === 'up') grid[j][i] = line[j];
      else grid[SIZE - 1 - j][i] = line[j];
    }
  }

  function move(dir) {
    if (dir !== 'left' && dir !== 'right' && dir !== 'up' && dir !== 'down') return false;
    var before = cloneGrid(grid);
    var gained = 0;
    for (var i = 0; i < SIZE; i++) {
      var res = collapse(readLine(dir, i));
      gained += res.gained;
      writeLine(dir, i, res.line);
    }
    var changed = false;
    for (var r = 0; r < SIZE && !changed; r++) {
      for (var c = 0; c < SIZE; c++) {
        if (before[r][c] !== grid[r][c]) { changed = true; break; }
      }
    }
    if (!changed) return false;
    score += gained;
    spawn();
    render();
    return true;
  }

  function render() {
    boardEl.innerHTML = '';
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = grid[r][c];
        var d = document.createElement('div');
        d.className = 'tile ' + (v === 0 ? 'empty' : (v > 2048 ? 'vbig' : 'v' + v));
        d.textContent = v === 0 ? '' : String(v);
        boardEl.appendChild(d);
      }
    }
    scoreEl.textContent = String(score);
  }

  function reset() {
    grid = emptyGrid();
    score = 0;
    spawn();
    spawn();
    render();
  }

  function setBoard(arr) {
    var g = emptyGrid();
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = arr && arr[r] ? arr[r][c] : 0;
        g[r][c] = Number(v) || 0;
      }
    }
    grid = g;
    render();
  }

  var KEYS = {
    ArrowLeft: 'left', ArrowRight: 'right', ArrowUp: 'up', ArrowDown: 'down',
    Left: 'left', Right: 'right', Up: 'up', Down: 'down'
  };

  document.addEventListener('keydown', function (e) {
    var dir = KEYS[e.key];
    if (!dir) return;
    e.preventDefault();
    move(dir);
  });

  resetEl.addEventListener('click', reset);

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: function () { return cloneGrid(grid); },
    setBoard: setBoard,
    score: function () { return score; }
  };

  reset();
})();
</script>
</body>
</html>
